contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call c.play{value: amount}() with amount provided by the caller.
    // The test observes address(c).balance and the InvMutTest contract balance before/after
    // to assert that when a payout happens (pot becomes 0) the caller received the pot minus fee,
    // and the bank received the fee. We cannot read internal bank balance, but transfers to bank
    // reduce address(c).balance by FEE_AMOUNT when payout happens while the caller receives pot-FEE.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read observable before-values
        uint beforePot = c.pot();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // general rule asserted for all inputs:
        // If call reverted then state didn't change (pot and balances unchanged).
        // If call did not revert and amount == TICKET_AMOUNT then either:
        //  - payout occurred: pot became 0, contract balance decreased by at least 1 (the fee),
        //    and caller's balance increased by (beforeCBalance - afterCBalance) - 0 or more (net received),
        //    and specifically the contract's pot is 0; OR
        //  - no payout: pot increased by amount and contract balance increased by amount.
        // We encode this as a single assert combining these observable consequences.

        assert(
            // if reverted then nothing observable changed
            (reverted && afterPot == beforePot && afterCBalance == beforeCBalance && afterThis == beforeThis)
            ||
            // if not reverted, two cases depending on whether pot reset to 0
            (!reverted && amount == C(address(c)).TICKET_AMOUNT() && (
                // payout case: pot becomes 0 and contract balance decreased by at least FEE_AMOUNT
                (afterPot == 0 && beforeCBalance >= afterCBalance && (beforeCBalance - afterCBalance) >= C(address(c)).FEE_AMOUNT()
                    && afterThis >= beforeThis)
                ||
                // no payout case: pot increased by amount and contract balance increased by amount
                (afterPot == beforePot + amount && afterCBalance == beforeCBalance + amount)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
