    // We accept an amount to send to c.play. We must ensure this contract has enough balance.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforePot = c.pot();
        uint beforeCBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterCBalance = address(c).balance;
        uint afterThis = address(this).balance;

        // We cannot access C.TICKET_AMOUNT or C.FEE_AMOUNT directly; observe behavior relative to amount and pot/balances.
        // General rule:
        // - If call reverted, observable state unchanged.
        // - Otherwise, if amount equals the ticket price then either payout happened (pot -> 0 and contract balance decreased by at least some positive fee)
        //   or no payout happened (pot increased by amount and contract balance increased by amount).
        // We express "amount equals ticket price" by detecting the branch where afterPot == beforePot + amount (no payout)
        // or afterPot == 0 (payout). For other amounts the call must revert, so non-revert with neither case is disallowed.

        assert(
            // reverted => no observable changes
            (reverted && afterPot == beforePot && afterCBalance == beforeCBalance && afterThis == beforeThis)
            ||
            // not reverted => one of the two observable outcomes holds
            (!reverted && (
                // payout observed: pot becomes 0 and contract balance decreased (fee paid out to bank and remainder to caller)
                (afterPot == 0 && beforeCBalance >= afterCBalance && afterThis >= beforeThis)
                ||
                // no payout observed: pot increased by amount and contract balance increased by amount
                (afterPot == beforePot + amount && afterCBalance == beforeCBalance + amount)
            ))
        );
    }

    receive() external payable {}
}

