contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount: Ether to send to c.play; caller of this run is the test harness,
    // but this contract is the msg.sender when calling c.play.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforePot = c.pot();
        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterCBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General rule:
        // - If amount != TICKET_AMOUNT then call must revert and neither pot nor contract balance change.
        // - If amount == TICKET_AMOUNT then call must NOT revert, and either:
        //     a) no payout: pot increased by amount, contract balance increased by amount, caller balance unchanged;
        //     b) payout happened: pot == 0, contract balance decreased (compared to before), and caller balance increased (received payout).
        // We cannot reference TICKET_AMOUNT directly, so express equality/inequality by observing behavior.

        // Implemented as single assert combining both cases.
        assert(
            // Case: call reverted -> must be when amount != ticket price, observable state unchanged
            (reverted && afterPot == beforePot && afterCBalance == beforeCBalance)
            ||
            // Case: not reverted -> must be amount == ticket price and either payout or no-payout with described balance effects
            (!reverted && (
                // No-payout branch: pot increased by exactly amount and contract balance increased by amount and caller balance unchanged
                (afterPot == beforePot + amount && afterCBalance == beforeCBalance + amount && afterMyBalance == beforeMyBalance)
                ||
                // Payout branch: pot reset to 0, contract balance decreased (paid out + fee), and caller balance increased (received payout)
                (afterPot == 0 && afterCBalance < beforeCBalance && afterMyBalance > beforeMyBalance)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call with some ether amount; we only consider the behavior when amount == TICKET_AMOUNT
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read pot before
        uint pot_before = c.pot();

        // perform the state-changing call, capturing whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();

        // General rule: if the caller paid exactly the ticket amount, then the pot increases by at most that ticket amount
        // (it might be reset to 0 on a payout, in which case pot_after can be less than pot_before; but it must never increase by more than amount)
        // We express: if amount == TICKET_AMOUNT and the call did not revert, then pot_after - pot_before <= amount
        // To avoid underflow in the assert, branch the difference safely.
        uint T = c.TICKET_AMOUNT();
        if (amount == T && !reverted) {
            if (pot_after >= pot_before) {
                assert(pot_after - pot_before <= amount);
            } else {
                // pot decreased due to payout; that's allowed
                assert(true);
            }
        } else {
            // For other cases (reverted or different amount) we make a weaker requirement: the test must still reach the assert
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send an amount to c.play(); capture whether it reverts and check pot change
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint pot_before = c.pot();

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();

        // We know from the referenced contract that the ticket amount constant is 10.
        // The rule: if we sent exactly 10 and the call did not revert, then pot_after - pot_before is either 0 or exactly amount.
        if (amount == 10 && !reverted) {
            if (pot_after >= pot_before) {
                assert(pot_after - pot_before == amount);
            } else {
                // pot decreased due to payout to the player; allowed to go to 0
                assert(pot_after == 0);
            }
        } else {
            // If other amounts or reverted, still reach the assert (no additional requirement)
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the ticket amount as input and sending it
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read before-values
        uint beforeContractBalance = address(c).balance;
        uint beforePot = c.pot();

        // perform the call and capture whether it reverted
        bool reverted = false;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterContractBalance = address(c).balance;
        uint afterPot = c.pot();

        // We only assert a conservation property for non-reverting calls with the exact ticket amount.
        // If the call did not revert and amount equals the known ticket price, then the total
        // Ether held by the contract (its balance) plus its reported pot must have grown exactly by amount.
        assert(reverted || amount != 10 || (afterContractBalance + afterPot == beforeContractBalance + beforePot + amount));
    }

    receive() external payable {}
}
